      "location": "를 적어주세요.",
      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n8월 초부터 차례대로) MPV 23년 6월이후 신차 구입자 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.07.31. 16:58\n조회 10\n구독\n8월 초부터 차례대로) MPV 23년 6월이후 신차 구입자 조사\n신청하신분은 재신청 안하셔도 됩니다\nMPV 차량을 23년 6월 이후 신차 구입하신 분 대상의 조사가 있습니다.\nMPV 차량은 하기 차량을 대상으로 진행됩니다.\n현대 스타리아 라운지, 현대 스타리아 리무진, 기아 카니발 하이리무진, 토요타 알파드, 렉서스 LM500h\n조사는 온라인 조사, 좌담회, 자동차 품평회가 있고, 해당 되는 조사를 추후 안내 드릴 예정입니다.\n<공통조건>\n1. 만 25세~64세 남여\n2. 23년 6월 이후 MPV 신차 구입자\n3. 자동차 관련업 종사자 제외\n사전에 차량등록증 사진을 찍어서 보내 주셔야 하니 참고 부탁 드립니다.\n자세한 사항은 신청자나 문의자에 한해 추가 설명 드리겠습니다.\n내용 확인 하시고 많은 신청 부탁드립니다.\n감사합니다.\n<진행일정>\n8월 초부터 차례대로 진행 될 예정입니다.\n사례비 : 10만원 + @\n(조사마다 금액이 달라 추후 조사 안내시 금액 재 안내 예정)\n소요시간\n30분 내외(온라인설문)\n2시간 반(좌담회, 자동차 품평회)\n신청시\n1. 성명, 성별, 연령, 연락처, 거주지역, 직업(구체적),\n2. 현재 댁에 보유하고 있는 총 차량 대수\n3. 현재 보유하고 있는 차량명, 구입시기, 연료타입, 트림, 몇인승인지?, 명의자, 명의자와의 관계\n4. 그 중 가장 주로 운행하는 차량을 기재해 주세요.\n5. 1열, 2열 중 주로 탑승하시는 위치를 적어주세요.\n7. 차량등록증 사진 보내주시는 것에 동의하시나요?\nhttps://forms.gle/GKcz3CKeWychtySS9\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.07.31. 19:34 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n30-59세 남성) 1시간15만) 자동차 (그랜져)차량 조사\n좌담회알바좌담회카페\n26.07.31.\n댓글\n1\n8월 초부터 차례대로) MPV 23년 6월이후 신차 구입자 조사\n좌담회알바좌담회카페\n26.07.31.\n댓글\n1\n8/11)만 20~29세 대학생 기혼여성)디저트 관련 조사(8월)\n좌담회알바좌담회카페\n26.07.31.\n댓글\n1\n8/11)만 20~29세 대학생 미혼여성)디저트 관련 조사(8월)\n좌담회알바좌담회카페\n26.07.31.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
