      "date": "8월 20일(목) 오후 7시 만 30~49세 남성 / 사무직, 자영업",
      "time": "약 2시간 30분",
      "duration": "약 2시간 30분",
      "reward": "80,000원(사전과제 제출 및 좌담회 참석 완료 시 지급)",
      "location": "서초구 서래마을 부근",
      "type": "좌담회",
      "raw_content": "[만28~49세 남녀]음료 좌담회-편의점 음료 구매자 8월 20일~25일[8만원]\n​\n최근 6개월 음료 구입빈도가 최근 1년 음료 구입빈도보다 감소한 분\n블루컬러 종사자들\n​\n대상 : 편의점에서 주 3회 이상 음료를 자주 구매하시는 분\n편의점에서 비타500, 박카스, 탄산, 커피 등 다양한 음료를 구매하시는 분\n작년 대비 구매 빈도가 증가한 분, 감소한 분 모두 선정 예정\n일정 : 8월 20일(목) 오후 7시 만 30~49세 남성 / 사무직, 자영업\n8월 21일(금) 오후 2시 만 28~39세 여성 / 사무직, 프리랜서, 자영업\n8월 21일(금) 오후 7시 만 28~49세 남성 / 블루칼라(현장, 시설관리, 생산, 건설, 물류, 운송, 정비 등)\n8월 24일(월) 오후 7시 만 40~49세 남성 / 사무직, 자영업\n8월 25일(화) 오후 7시 만 28~39세 남성 / 사무직\n방법 : 좌담회(사전과제 필수)\n소요시간 : 약 2시간 30분\n사례비 : 80,000원(사전과제 제출 및 좌담회 참석 완료 시 지급)\n장소 : 서초구 서래마을 부근\n안내사항 : 본 조사는 좌담회 참석 전 사전과제를 수행하셔야 하며 사전과제 제출 및\n좌담회 참석까지 모두 완료하셔야 사례비가 지급됩니다.\n3~4일 동안 진행되는 사전과제를 성실하게 수행하실 분만 신청 부탁드립니다.\n사전과제 일정 : 8월 7일(금) 사전과제 송부\n8월 7일(금) ~ 8월 12일(수) 사전과제 진행\n8월 13일(목) ~ 8월 14일(금) 사전과제 수정 및 보완\n소개자명\n하진혁\n필히 기입 바랍니다.\n​\n신청하기",
